let sharedPage = "not created yet";        // module scope — visible everywhere below

function createsIt() {
  sharedPage = "created inside a function";   // assigns to the outer one
  const localOnly = "invisible outside";
  return localOnly;
}

function readsIt() {
  return `readsIt sees: ${sharedPage}`;       // works, because sharedPage is module scope
}

console.log("before:", sharedPage);
createsIt();
console.log("after: ", sharedPage);
console.log(readsIt());

import { launch, login, BASE_URL } from "../_shared/deno-helpers.ts";
import { chromium } from "npm:playwright";

const browser = await chromium.launch();

const describe = async (label: string, p: any) => {
  const body = (await p.locator("body").innerText()).replace(/\s+/g, " ");
  console.log(`${label.padEnd(22)} url=${p.url().split("/").pop()}  "Leela" present=${body.includes("Leela")}`);
};

// Context A — log in
const ctxA = await browser.newContext();
const pageA = await ctxA.newPage();
await pageA.goto(BASE_URL);
await pageA.getByPlaceholder("Enter Email").fill("leela@gmail.com");
await pageA.getByPlaceholder("Enter Password").fill("Leela@123");
await pageA.getByRole("button", { name: "Login" }).click();
await pageA.waitForURL("**/dashboard");
await describe("A: signed in", pageA);

// Context B — brand new, same browser, straight to the dashboard URL
const ctxB = await browser.newContext();
const pageB = await ctxB.newPage();
await pageB.goto(`${BASE_URL}dashboard`);
await describe("B: fresh context", pageB);

// And the isolation itself, proved with storage we control
await pageA.evaluate(() => localStorage.setItem("proof", "written in A"));
console.log("A localStorage.proof:", await pageA.evaluate(() => localStorage.getItem("proof")));
console.log("B localStorage.proof:", await pageB.evaluate(() => localStorage.getItem("proof")));

await ctxA.close();
await ctxB.close();

// This is what beforeAll does, written out so you can watch it.
let sharedPage = await browser.newPage();      // `let`, declared outside — Day 2.1
await sharedPage.goto(BASE_URL);
await sharedPage.getByPlaceholder("Enter Email").fill("leela@gmail.com");
await sharedPage.getByPlaceholder("Enter Password").fill("Leela@123");
await sharedPage.getByRole("button", { name: "Login" }).click();
await sharedPage.waitForURL("**/dashboard");
console.log("logged in once:", sharedPage.url());

// Now three "tests" reuse it — no second login
for (const tile of ["Transaction History", "Pay Bills", "Add Payee"]) {
  await sharedPage.goto(`${BASE_URL}dashboard`);
  await sharedPage.getByText(tile, { exact: true }).click();
  console.log(`  ${tile.padEnd(20)} -> ${sharedPage.url().split("/").pop()}`);
}

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 4 Day 1.1, concept 2.

await writeProjectFile("week3/generated/day2-hooks.spec.ts", `// Week 3, Day 2 — one login, shared across dependent tests.
//
// The three journeys below all need a logged-in session. Rather than log in three
// times, beforeAll logs in once and hands the same page to every test.
//
// Written by a cell in week3/day2_2.ipynb. Run it yourself:
//   npx playwright test week3/generated/day2-hooks.spec.ts
import { test, expect, type Browser, type Page } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

// Declared with \`let\`, at module scope, because it is created in beforeAll and
// used by every test below. A \`const\` inside the hook would vanish with the hook.
let page: Page;

test.describe("Dashboard journeys, sharing one login", () => {
  // These tests share a page, so they must not run at the same time as each other.
  test.describe.configure({ mode: "serial" });

  // \`browser\` is worker-scoped, so it IS available in beforeAll. \`page\` is
  // test-scoped and would not be — which is exactly why we build our own here.
  test.beforeAll(async ({ browser }: { browser: Browser }) => {
    page = await browser.newPage();
    await loginAs(page);
  });

  test.afterAll(async () => {
    // Cleanup belongs with the thing that created the resource.
    await page.close();
  });

  test("Step 1 — we are genuinely signed in", async () => {
    await expect(page).toHaveURL(/\\/dashboard/);
    // The user's name only renders for a real session. Asserting on the URL or on
    // "Account Balance" would NOT prove sign-in on this app — see the last test.
    await expect(page.getByText("Leela")).toBeVisible();
  });

  test("Step 2 — Transaction History opens the account view", async () => {
    await page.getByText("Transaction History", { exact: true }).click();
    await expect(page).toHaveURL(/accountDashboard/);
  });

  test("Step 3 — Pay Bills opens the payment view", async () => {
    await page.goto("/dashboard");
    await page.getByText("Pay Bills", { exact: true }).click();
    await expect(page).toHaveURL(/paymentDashboard/);
  });

  test("Step 4 — Add Payee opens the transfer view", async () => {
    await page.goto("/dashboard");
    await page.getByText("Add Payee", { exact: true }).click();
    await expect(page).toHaveURL(/transferDashboard/);
  });
});

test.describe("What the \`page\` fixture does instead", () => {
  // No beforeAll, no shared state. Playwright hands each test its own fresh
  // context — no cookies, no storage, nothing carried over from the test before.
  test("each test starts at the login form", async ({ page }) => {
    await page.goto("/");
    await expect(page.getByPlaceholder("Enter Email")).toBeVisible();
  });

  test("a fresh context reaches /dashboard but is NOT signed in", async ({ page }) => {
    await page.goto("/dashboard");

    // Surprising, and worth knowing: this app has no route guard, so the dashboard
    // shell renders for anybody who types the URL.
    await expect(page).toHaveURL(/dashboard/);
    await expect(page.getByText("Account Balance", { exact: true })).toBeVisible();

    // But the signed-in user's name is absent, which is what actually proves the
    // session did not carry over. Assert on user data, never on reaching a URL.
    await expect(page.getByText("Leela")).toHaveCount(0);
  });

  test("storage set in one test cannot be seen by another", async ({ page }) => {
    await page.goto("/");
    const leaked = await page.evaluate(() => localStorage.getItem("week3-proof"));
    // Nothing here, however many times this file has run before.
    expect(leaked).toBeNull();
    await page.evaluate(() => localStorage.setItem("week3-proof", "written"));
  });
});
`);

await runSpec("week3/generated/day2-hooks.spec.ts");

// Which tool fits which situation. Read it as a decision table.
const decisions = [
  { situation: "tests genuinely independent",        use: "page fixture, no hooks" },
  { situation: "each test needs a fresh login",      use: "beforeEach" },
  { situation: "expensive setup, read-only after",   use: "beforeAll + shared page" },
  { situation: "many tests need the same login",     use: "storageState" },
  { situation: "test B needs data test A created",   use: "make B create its own data" },
];

for (const d of decisions) {
  console.log(`${d.situation.padEnd(34)} -> ${d.use}`);
}
